arguments.file_text:
@{
    var steps = new[] { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
}

<nav class="step-indicator mb-4">
    <ol class="step-list">
        @for (int i = 0; i < steps.Length; i++)
        {
            var stepNumber = i + 1;
            var isActive = stepNumber == CurrentStep;
            var isCompleted = CompletedSteps.Contains(stepNumber);
            var cssClass = isActive ? "active" : isCompleted ? "completed" : "future";

            <li class="step-item @cssClass">
                @if (isCompleted && !isActive)
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(stepNumber)">
                        <span class="step-circle">✓</span>
                        <span class="step-label">@steps[i]</span>
                    </button>
                }
                else
                {
                    <div class="step-button">
                        <span class="step-circle">@stepNumber</span>
                        <span class="step-label">@steps[i]</span>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

.step-indicator {
    padding: 0.5rem 0;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
    position: relative;
}

.step-list::before {
    content: "";
    position: absolute;
    top: 18px;
    left: 10%;
    right: 10%;
    height: 2px;
    background: #dee2e6;
    z-index: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    z-index: 1;
}

.step-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    padding: 0;
    cursor: default;
    gap: 0.4rem;
}

.completed .step-button {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    background: #e9ecef;
    color: #adb5bd;
    transition: all 0.2s;
}

.active .step-circle {
    background: #0d6efd;
    color: #fff;
}

.completed .step-circle {
    background: #198754;
    color: #fff;
}

.step-label {
    font-size: 0.8rem;
    color: #adb5bd;
    text-align: center;
    white-space: nowrap;
}

.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.completed .step-label {
    color: #198754;
}

@{
    var steps = new[] { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
}

<nav class="step-indicator mb-4">
    <ol class="step-list">
        @for (int i = 0; i < steps.Length; i++)
        {
            var stepNumber = i + 1;
            var isActive = stepNumber == CurrentStep;
            var isCompleted = CompletedSteps.Contains(stepNumber);
            var cssClass = isActive ? "active" : isCompleted ? "completed" : "future";

            <li class="step-item @cssClass">
                @if (isCompleted && !isActive)
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(stepNumber)">
                        <span class="step-circle">✓</span>
                        <span class="step-label">@steps[i]</span>
                    </button>
                }
                else
                {
                    <div class="step-button">
                        <span class="step-circle">@stepNumber</span>
                        <span class="step-label">@steps[i]</span>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

@code {
