@page "/apply"
@rendermode InteractiveServer
@using sv_6e1972723d3f461599c7ee51fa58fc61.Components.Apply

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h1 class="mb-4">Job Application</h1>

    @if (_submitted)
    {
        <div class="alert alert-success text-center my-5 py-5">
            <h3 class="mb-3">🎉 Application Submitted!</h3>
            <p class="lead">Your application ID is: <strong>#@_applicationId</strong></p>
            <p class="text-muted">Please save this ID for your records.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="_currentStep"
                       CompletedSteps="_completedSteps"
                       OnStepClicked="GoToStep" />

        <div class="mt-4">
            @switch (_currentStep)
            {
                case 1:
                    <PersonalInfoStep Model="_personalInfo" OnNext="HandleStepNext" />
                    break;
                case 2:
                    <WorkHistoryStep Entries="_workEntries" OnBack="GoBack" OnNext="HandleStepNext" />
                    break;
                case 3:
                    <ReferencesStep References="_references" OnBack="GoBack" OnNext="HandleStepNext" />
                    break;
                case 4:
                    <CoverLetterStep @bind-CoverLetter="_coverLetter" OnBack="GoBack" OnNext="HandleStepNext" />
                    break;
                case 5:
                    <ReviewStep PersonalInfo="_personalInfo"
                                WorkEntries="_workEntries"
                                References="_references"
                                CoverLetter="@_coverLetter"
                                OnEdit="GoToStep"
                                OnSubmit="HandleSubmit"
                                OnBack="GoBack" />
                    break;
            }
        </div>
    }
</div>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private int _currentStep = 1;
    private readonly HashSet<int> _completedSteps = new();
    private bool _submitted;
    private int _applicationId;

    // Form state
    private readonly PersonalInfoModel _personalInfo = new();
    private readonly List<WorkEntryModel> _workEntries = [new()];
    private readonly List<ReferenceModel> _references = [new(), new()];
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        if (_completedSteps.Contains(step))
            _currentStep = step;
    }

    private void GoBack()
    {
        if (_currentStep > 1)
            _currentStep--;
    }

    private void HandleStepNext()
    {
        _completedSteps.Add(_currentStep);
        if (_currentStep < 5)
            _currentStep++;
    }

    private async Task HandleSubmit()
    {
        var application = new JobApplication(
            new PersonalInfo(_personalInfo.FullName, _personalInfo.Email, _personalInfo.Phone, _personalInfo.Address),
            new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.Today, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
            _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            _coverLetter
        );

        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
        _submitted = true;
    }
}

